def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--print-only", action="store_true", help="Build and print the report without sending it.")
    parser.add_argument("--send", action="store_true", help="Deliver the completed report through SAL's Node-RED iMessage sender.")
    args = parser.parse_args()
    try:
        report = get_report()
        print(report)
        if args.send:
            send_to_recipients(report)
        return 0
    except Exception as exc:
        print(f"Ledger — Daily Unpaid Invoice Report\n\nERROR: {exc}", file=sys.stdout)
        if args.send:
            alert_william(exc)
        return 1
